{
  "commit": "624a67329fe2ad440c5b344785a9c73fcf22ae63",
  "component": "tome",
  "directional_value_flow": [
    {
      "direction": "getMaxAbsorb -> first tooltip shield capacity; callbackOnHit consumes shield power without storage",
      "expression": "t.getMaxAbsorb(self,t)",
      "index": 1,
      "quantity_kind": "shield"
    },
    {
      "direction": "ratio -> mana_usage=store*ratio; tooltip conversion ratio",
      "expression": "t.getManaRatio(self,t)",
      "index": 2,
      "quantity_kind": "mana_per_damage"
    },
    {
      "direction": "total mana capped at getMaxDamageLimit -> *2 -> storage cap; explode applies same cap",
      "expression": "t.getMaxDamage(self,t)",
      "index": 3,
      "quantity_kind": "damage"
    },
    {
      "direction": "radius -> map:addEffect radius",
      "expression": "self:getTalentRadius(t)",
      "index": 4,
      "quantity_kind": "distance"
    },
    {
      "direction": "upper bound of total mana for storage cap",
      "expression": "t.getMaxDamageLimit(self,t)",
      "index": 5,
      "quantity_kind": "mana"
    },
    {
      "direction": "current remaining ordinary shield capacity displayed",
      "expression": "self.disruption_shield_power or 0",
      "index": 6,
      "quantity_kind": "shield"
    },
    {
      "direction": "mana-absorbed store accumulated then possibly decayed/consumed -> displayed current storage -> deactivate -> explode min(cap) -> spellCrit(dam/5) -> five-turn ARCANE effect",
      "expression": "self.disruption_shield_storage or 0",
      "index": 7,
      "quantity_kind": "damage"
    }
  ],
  "facts": [
    {
      "excerpt": "168: \texplode = function(self, t, dam)\n169: \t\tgame.logSeen(self, \"#VIOLET#%s's disruption shield collapses and then explodes in a powerful manastorm!\", self:getName():capitalize())\n170: \t\tdam = math.min(dam, t.getMaxDamage(self, t)) -- Damage cap\n171: \t\t-- Add a lasting map effect\n172: \t\tlocal radius = self:getTalentRadius(t)\n173: \t\tgame.level.map:addEffect(self,\n174: \t\t\tself.x, self.y, 5,\n175: \t\t\tDamageType.ARCANE, self:spellCrit(dam / 5),\n176: \t\t\tradius,\n177: \t\t\t5, nil,\n178: \t\t\t{type=\"arcanestorm\", args={radius=radius}, only_one=true},\n179: \t\t\tfunction(e) e.x = e.src.x e.y = e.src.y return true end,\n180: \t\t\tfalse\n181: \t\t)",
      "note": "explode caps supplied damage, then applies spellCrit(dam/5) each turn in a five-turn effect.",
      "range": [
        168,
        181
      ]
    },
    {
      "excerpt": "202: \tcallbackOnAct = function(self, t, state)\n203: \t\tif self.in_combat then return end\n204: \t\tself.disruption_shield_power = self.disruption_shield_power or 0\n205: \t\tself.disruption_shield_storage = self.disruption_shield_storage or 0\n206: \t\tself.disruption_shield_storage = self.disruption_shield_storage / 3\n207: \t\tif self.disruption_shield_storage < 100 then self.disruption_shield_storage = 0 end\n208: \t\tlocal max = t.getMaxAbsorb(self, t)\n209: \t\tself.disruption_shield_power = math.min(self.disruption_shield_power + max / 10, max)",
      "note": "Outside combat, stored energy divides by 3 and is cleared below 100.",
      "range": [
        202,
        209
      ]
    },
    {
      "excerpt": "223: \tcallbackOnHit = function(self, t, cb, src, dt)\n224: \t\tlocal p = self:isTalentActive(t.id)\n225: \t\tif not p then return end\n226: \t\tif cb.value <= 0 then return end\n227: \t\tif self:getMana() / self:getMaxMana() < 0.5 then\n228: \t\t\tself:forceUseTalent(self.T_DISRUPTION_SHIELD, {ignore_energy=true})\n229: \t\t\treturn\n230: \t\tend\n231: \t\t-- if self:reactionToward(src) > 0 then return end\n232: \t\tself.disruption_shield_power = self.disruption_shield_power or 0\n233: \t\tself.disruption_shield_storage = self.disruption_shield_storage or 0\n234: \t\tlocal absorbed = 0\n235: \n236: \t\tif cb.value <= self.disruption_shield_power then\n237: \t\t\tself.disruption_shield_power = self.disruption_shield_power - cb.value\n238: \t\t\tabsorbed = cb.value\n239: \t\t\tcb.value = 0\n240: \t\t\tgame:delayedLogDamage(src, self, 0, (\"#SLATE#(%d absorbed)#LAST#\"):tformat(absorbed), false)\n241: \t\t\tp.was_depleted = false\n242: \t\t\treturn true\n243: \t\telse\n244: \t\t\tcb.value = cb.value - self.disruption_shield_power\n245: \t\t\tabsorbed = self.disruption_shield_power\n246: \t\t\tself.disruption_shield_power = 0\n247: \t\tend",
      "note": "Normal shield power absorbs damage without adding storage; only remainder reaches mana branch.",
      "range": [
        223,
        247
      ]
    },
    {
      "excerpt": "257: \t\tlocal do_explode = false\n258: \t\tlocal ratio = t.getManaRatio(self, t)\n259: \t\tlocal mana_usage = cb.value * ratio\n260: \t\tlocal store = cb.value\n261: \n262: \t\tif self.disruption_shield_storage + store >= t.getMaxDamage(self, t) then\n263: \t\t\tdo_explode = true\n264: \t\t\tstore = t.getMaxDamage(self, t) - self.disruption_shield_storage\n265: \t\t\tmana_usage = store * ratio\n266: \t\tend\n267: \t\tif (self:getMana() - mana_usage) / self:getMaxMana() < 0.5 then\n268: \t\t\tdo_explode = true\n269: \t\t\tlocal mana_limit = self:getMaxMana() * 0.3\n270: \t\t\tmana_usage = self:getMana() - mana_limit\n271: \t\t\tstore = mana_usage / ratio\n272: \t\tend\n273: \t\tcb.value = cb.value - store\n274: \t\tabsorbed = absorbed + store\n275: \t\tself:incMana(-mana_usage)\n276: \t\tself.disruption_shield_storage = math.min(self.disruption_shield_storage + store, t.getMaxDamage(self, t))",
      "note": "Mana branch computes store from remaining incoming damage and caps storage separately from the total absorbed value.",
      "range": [
        257,
        276
      ]
    },
    {
      "excerpt": "287: \tdoAegis = function(self, t, val)\n288: \t\tlocal energy = self.disruption_shield_storage or 0\n289: \t\tlocal max = t.getMaxAbsorb(self, t)\n290: \t\tlocal eneed = (max - self.disruption_shield_power) * 2\n291: \n292: \t\tif eneed < energy then\n293: \t\t\tself.disruption_shield_power = max\n294: \t\t\tself:incMana((energy - eneed) * val / 100)\n295: \t\t\tgame.logSeen(self, \"%s restores Disruption Shield (+%d) and gains %d mana with Aegis!\", self:getName(), eneed/2, (energy - eneed) * val / 100)\n296: \t\telse\n297: \t\t\tself.disruption_shield_power = self.disruption_shield_power + energy / 2\n298: \t\t\tgame.logSeen(self, \"%s restores Disruption Shield (+%d) with Aegis!\", self:getName(), energy / 2)\n299: \t\tend\n300: \t\tself.disruption_shield_storage = 0",
      "note": "Aegis consumes stored energy and resets storage to zero.",
      "range": [
        287,
        300
      ]
    },
    {
      "excerpt": "326: \tdeactivate = function(self, t, p)\n327: \t\tself:removeParticles(p.particle)\n328: \t\tif self:attr(\"save_cleanup\") then return true end\n329: \n330: \t\t-- Explode!\n331: \t\tif self.disruption_shield_storage and self.disruption_shield_storage > 0 then t.explode(self, t, self.disruption_shield_storage) end\n332: \t\tself.disruption_shield_storage = nil",
      "note": "deactivate passes current disruption_shield_storage into explode.",
      "range": [
        326,
        332
      ]
    }
  ],
  "kind": "host_fixed_source_observations",
  "path": "game/modules/tome/data/talents/spells/arcane.lua",
  "read_at": "2026-09-12T07:56:32.676972+00:00",
  "revision": "2715030b9b9769ac1507ab94d08066f894c855d06380617011b3fa5c00012713",
  "source_file_sha256": "b1b1401244611b4bf3bd1ae39c8a6a44256c16e5792a81c21a71d80ceb2fc835",
  "visibility": "host only; not sent to independent reviewer"
}

